import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import "../styles/main.css";

export default function AdminGallery() {
  const [images, setImages] = useState([]);
  const [file, setFile] = useState(null);

  // Fetch gallery images from backend
  const fetchImages = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/gallery");
      setImages(res.data || []);
    } catch (err) {
      console.error(err);
      toast.error("Failed to load images");
    }
  };

  useEffect(() => {
    fetchImages();
  }, []);

  // Upload new image
  const uploadImage = async () => {
    if (!file) return toast.error("Select an image first");
    const formData = new FormData();
    formData.append("image", file);

    try {
      const res = await axios.post("http://localhost:5000/api/gallery", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      if (res.data.success) {
        toast.success("Image uploaded!");
        fetchImages();
        setFile(null);
      } else toast.error("Upload failed");
    } catch (err) {
      console.error(err);
      toast.error("Upload failed");
    }
  };

  // Delete image
  const deleteImage = async (id) => {
    try {
      const res = await axios.delete(`http://localhost:5000/api/gallery/${id}`);
      if (res.data.success) {
        toast.success("Deleted!");
        fetchImages();
      } else toast.error("Delete failed");
    } catch (err) {
      console.error(err);
      toast.error("Delete failed");
    }
  };

  return (
    <div className="admin-gallery-page">
      <Toaster />
      <h2>Manage Gallery</h2>

      <div className="upload-section">
        <input type="file" onChange={(e) => setFile(e.target.files[0])} />
        <button onClick={uploadImage}>Upload</button>
      </div>

      <div className="gallery-grid">
        {images.map((img) => (
          <div className="gallery-card" key={img._id}>
            <img src={img.url} alt={img.title || "Gallery"} />
            <button className="delete-btn" onClick={() => deleteImage(img._id)}>Delete</button>
          </div>
        ))}
      </div>
    </div>
  );
}
